-- =============================================================================
-- HAND-WRITTEN additions
-- =============================================================================

-- Full-text search vector, maintained by trigger (a generated column cannot use
-- array_to_string, which is not IMMUTABLE). 'simple' config: catalogue is multilingual.
CREATE OR REPLACE FUNCTION webcenta_listing_search_vector() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
BEGIN
  NEW."searchVector" :=
    setweight(to_tsvector('simple', coalesce(NEW.name, '')), 'A') ||
    setweight(to_tsvector('simple', coalesce(NEW.tagline, '')), 'B') ||
    setweight(to_tsvector('simple', coalesce(NEW."publisherName", '')), 'B') ||
    setweight(to_tsvector('simple', coalesce(array_to_string(NEW.features, ' '), '')), 'C') ||
    setweight(to_tsvector('simple', coalesce(NEW.description, '')), 'D');
  RETURN NEW;
END $$;

CREATE TRIGGER "Listing_searchVector_trg"
  BEFORE INSERT OR UPDATE OF name, tagline, "publisherName", features, description
  ON "Listing" FOR EACH ROW EXECUTE FUNCTION webcenta_listing_search_vector();

-- Integrity checks (Prisma does not model CHECK constraints; they are not drift).
ALTER TABLE "Review" ADD CONSTRAINT "Review_rating_range" CHECK (rating BETWEEN 1 AND 5);
ALTER TABLE "GeoRestriction" ADD CONSTRAINT "GeoRestriction_one_target"
  CHECK (("listingId" IS NULL) <> ("categoryId" IS NULL));
ALTER TABLE "GeoRestriction" ADD CONSTRAINT "GeoRestriction_country_format"
  CHECK ("countryCode" ~ '^[A-Z]{2}$');
ALTER TABLE "Category" ADD CONSTRAINT "Category_not_own_parent"
  CHECK ("parentId" IS NULL OR "parentId" <> id);
ALTER TABLE "Listing" ADD CONSTRAINT "Listing_slug_format"
  CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
ALTER TABLE "Listing" ADD CONSTRAINT "Listing_website_https"
  CHECK ("websiteUrl" ~ '^https://');
ALTER TABLE "Listing" ADD CONSTRAINT "Listing_rating_average_range"
  CHECK ("ratingAverage" >= 0 AND "ratingAverage" <= 5);

-- Row Level Security on EVERY table in "public".
-- Webcenta accesses Postgres only from the server, as the table owner (which
-- bypasses RLS). Supabase also exposes "public" through its Data API to the
-- anon/authenticated roles; enabling RLS with no policies denies them all access.
-- New tables in later migrations MUST enable RLS too (enforced by tests/db).
DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t.tablename);
  END LOOP;
END $$;

-- On Supabase, additionally revoke Data API roles' privileges (no-op elsewhere).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon';
    EXECUTE 'REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon';
    EXECUTE 'REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM anon';
    -- Also stop future tables created by this role from being granted automatically.
    EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon';
    EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon';
    EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA public FROM authenticated';
    EXECUTE 'REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM authenticated';
    EXECUTE 'REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM authenticated';
    EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM authenticated';
    EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM authenticated';
    EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM authenticated';
  END IF;
END $$;
